UPDATE results SET statement_tex = 'Let $\chi$ be a \hyperref[8JH4]{primitive character}, let $R_\chi$ and $G_\chi$ be as in the \hyperref[8JF7]{definition of the smoothed prime sum}, let
\[ M_\chi(x) = R_\chi(x) - G_\chi(x) = \begin{cases} x\log x - (1+\gamma)x, & \chi = \mathbf 1, \\[4pt] -x\,\dfrac{L''(1,\chi)}{L(1,\chi)}, & \chi \ne \mathbf 1, \end{cases} \]
be the main term, and let $c_{\mathbf 1} = 1+\gamma$ and $c_\chi = \bigl|L''(1,\chi)/L(1,\chi)\bigr|$ for $\chi \ne \mathbf 1$.
\begin{enumerate}
\item[(i)]  $|R_\chi(x)| \le x\log x\,(1+\log x)$ for $x \ge 1$.
\item[(ii)] $|M_\chi(x)| \le c_\chi\, x\,(1+\log x)$ for $x \ge 1$.
\item[(iii)] $|G_\chi(x)| \le (1+c_\chi)\, x\,(1+\log x)^2$ for $x \ge 1$. \\
In particular $G_\chi(x) = O_\varepsilon(x^{1+\varepsilon})$ for every $\varepsilon > 0$.
\end{enumerate}
See the \hyperref[8JS9]{example} of the trivial character.', statement_html_cache = NULL, revision = 4, updated_at = '2026-11-24 13:40:00', updated_by = 'claude' WHERE id = 116;
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('result', '116', 4, 'hide-example-2026-11-24', '{"tag":"8JS3","type":"lemma","title":"Growth of the smoothed prime sums","statement_tex":"Let $\\chi$ be a \\hyperref[8JH4]{primitive character}, let $R_\\chi$ and $G_\\chi$ be as in the \\hyperref[8JF7]{definition of the smoothed prime sum}, let\n\\[ M_\\chi(x) = R_\\chi(x) - G_\\chi(x) = \\begin{cases} x\\log x - (1+\\gamma)x, & \\chi = \\mathbf 1, \\\\[4pt] -x\\,\\dfrac{L''(1,\\chi)}{L(1,\\chi)}, & \\chi \\ne \\mathbf 1, \\end{cases} \\]\nbe the main term, and let $c_{\\mathbf 1} = 1+\\gamma$ and $c_\\chi = \\bigl|L''(1,\\chi)/L(1,\\chi)\\bigr|$ for $\\chi \\ne \\mathbf 1$.\n\\begin{enumerate}\n\\item[(i)]  $|R_\\chi(x)| \\le x\\log x\\,(1+\\log x)$ for $x \\ge 1$.\n\\item[(ii)] $|M_\\chi(x)| \\le c_\\chi\\, x\\,(1+\\log x)$ for $x \\ge 1$.\n\\item[(iii)] $|G_\\chi(x)| \\le (1+c_\\chi)\\, x\\,(1+\\log x)^2$ for $x \\ge 1$. \\\\\nIn particular $G_\\chi(x) = O_\\varepsilon(x^{1+\\varepsilon})$ for every $\\varepsilon > 0$.\n\\end{enumerate}\nSee the \\hyperref[8JS9]{example} of the trivial character.","section_id":102,"position":2,"listed":1,"aliases":["smoothed-sum-growth"]}', 'claude');
